<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import type { OnValueChange, Orientation } from '../shared/types.js'; import PopoverRoot from '../popover/PopoverRoot.svelte'; import { NavigationMenuState, setNavigationMenuContext } from './navigation-menu-context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; value?: string | null; onValueChange?: OnValueChange<string | null, 'trigger-press' | 'link-press'>; orientation?: Orientation; delay?: number; closeDelay?: number; ref?: HTMLDivElement | null; } let { children, value = $bindable(null), onValueChange, orientation = 'horizontal', ref = $bindable(null), ...rest }: Props = $props(); const uid = $props.id(); const navigation = setNavigationMenuContext(new NavigationMenuState()); navigation.baseId = uid; navigation.setValue = (next, event) => { value = next; onValueChange?.(next, { reason: next ? 'trigger-press' : 'link-press', event }); }; $effect.pre(() => { navigation.value = value; navigation.orientation = orientation; });</script>
<PopoverRoot open={value !== null} onOpenChange={(open) => { if (!open) value = null; }}><div bind:this={ref} {...rest} data-orientation={orientation} data-open={value !== null ? '' : undefined}>{@render children?.()}</div></PopoverRoot>
